  FT["PH-H6896"] = {"id":"PH-H6896","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8421_1997.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将巴拉望 Roxas，Abaroan 描笼涯的 Roxas 国立综合中学附属校改设为名为 Abaroan 国立中学的独立中学并拨款","en":"An Act Converting the Roxas National Comprehensive High School Annex At Barangay Abaroan, Roxas, Palawan, Into An Independent High School to Be Known as Abaroan National High School, and Appropriating Funds Therefor","orig":"An Act Converting the Roxas National Comprehensive High School Annex At Barangay Abaroan, Roxas, Palawan, Into An Independent High School to Be Known as Abaroan National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8421","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-11-27","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8421_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6896-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Barangay Abaroan Annex of the Roxas National Comprehensive High School in Roxas, Palawan, shall be converted to a national high school to be known as Abaroan National High School."}},{"id":"PH-H6896-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All assets, immovable and movable, and records of Roxas National Comprehensive High School Annex at Barangay Abaroan, as well as its liabilities or obligations, are hereby transferred to the Abaroan National High School: Provided, however , That the positions, rights and security of tenure of academic and nonacademic personnel who choose to remain and serve in the new school shall not be impaired."}},{"id":"PH-H6896-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6896-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Department of Education, Culture and Sports shall promulgate the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H6896-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect fifteen (15) days following the completion of its publication in two (2) newspapers of general and nationwide circulation."}}],"pack":"ph-p98","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Roxas National Comprehensive High School Annex At Barangay Abaroan, Roxas, Palawan, Into An Independent High School to Be Known as Abaroan National High School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6897"] = {"id":"PH-H6897","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8422_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将南阿古桑省Bayugan的Marcelina描笼涯由家长教师协会管理的中学改设为国立政府资助的中学，名称为Marcelina国立中学，并为此拨款的法案","en":"An Act Converting the High School Administered By the Parent-teachers' Association At Barangay Marcelina, Bayugan, Agusan Del Sur, Into A National Government-funded Secondary School To Be Known As the Marcelina National High School, and Appropriating Funds Therefor","orig":"An Act Converting the High School Administered By the Parent-teachers' Association At Barangay Marcelina, Bayugan, Agusan Del Sur, Into A National Government-funded Secondary School To Be Known As the Marcelina National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8422","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-11-27","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8422_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6897-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The high school owned and administered by the Parent-Teachers' Association at Barangay Marcelina, Municipality of Bayugan, Province of Agusan del Sur, is hereby converted into a national secondary school, under the control and supervision of the national government through the Department of Education, Culture and Sports."}},{"id":"PH-H6897-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This school shall be known officially as the Marcelina National High School."}},{"id":"PH-H6897-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6897-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p98","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the High School Administered By the Parent-teachers' Association At Barangay Marcelina, Bayugan, Agusan Del Sur, Into A National Government-funded Secondary School To Be Known As the Marcelina National High School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6898"] = {"id":"PH-H6898","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8423_1997.html","fetchedAt":"2026-10-06","articleCount":22,"structureMode":"ARTICLE","title":{"zh":"1997 年传统与替代医学法","en":"Traditional and Alternative Medicine Act (TAMA) of 1997","orig":"Traditional and Alternative Medicine Act (TAMA) of 1997 An Act Creating the Philippine Institute of Traditional and Alternative Health Care (PITAHC) to Accelerate the Development of Traditional and Alternative Health Care in the Philippines, Providing for a Traditional and Alternative Health Care Development Fund and for other purposes"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 8423","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-12-09","completenessNote":"全文，共 22 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8423_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6898-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. - This Act shall be known as the \" Traditional and Alternative Medicine Act (TAMA) of 1997. \" GUIDING PRINCIPLES"}},{"id":"PH-H6898-A2","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Declaration of Policy. - It is hereby declared the policy of the State to improve the quality and delivery of health care services to the Filipino people through the development of traditional and alternative health care and its integration into the national health care delivery system.\nIt shall also be the policy of the State to seek a legally workable basis by which indigenous societies would own their knowledge of traditional medicine. When such knowledge is used by outsiders, the indigenous societies can require the permitted users to acknowledge its source and can demand a share of any financial return that may come from its authorized commercial use."}},{"id":"PH-H6898-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Objectives. - The objectives of this Act are as follows:\n(a) To encourage scientific research on and develop traditional and alternative health care systems that have direct impact on public health care;\n(b) To promote and advocate the use of traditional, alternative, preventive and curative health care modalities that have been proven safe, effective, cost effective and consistent with government standards on medical practice;\n(c) To develop and coordinate skills training courses for various forms of traditional and alternative health care modalities;\n(d) To formulate standards, guidelines and codes of ethical practice appropriate for the practice of traditional and alternative health care as well as in the manufacture, quality control and marketing of different traditional and alternative health care materials, natural and organic products, for approval and adoption by the appropriate government agencies;\n(e) To formulate policies for the protection of indigenous and natural health resources and technology from unwarranted exploitation, for approval and adoption by the appropriate government agencies;\n(f) To formulate policies to strengthen the role of traditional and alternative health care delivery system; and\n(g) To promote traditional and alternative health care in international and national conventions, seminars and meetings in coordination with the Department of Tourism, Duty Free Philippines, Incorporated, Philippine Convention and Visitors Corporation and other tourism-related agencies as well as non-government organizations and local government units.\nDEFINITION OF TERMS"}},{"id":"PH-H6898-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Definition of Terms. - As used in this Act, the following terms shall mean:\n(a) \" Traditional and alternative health care \" - the sum total of knowledge, skills and practices on health care, other than those embodied in biomedicine, used in the prevention, diagnosis and elimination of physical or mental disorder.\n(b) \" Traditional medicine \" - the sum total of knowledge, skills, and practice on health care, not necessarily explicable in the context of modern, scientific philosophical framework, but recognized by the people to help maintain and improve their health towards the wholeness of their being, the community and society, and their interrelations based on culture, history, heritage, and consciousness.\n(c) \" Biomedicine \" - that discipline of medical care advocating therapy with remedies that produce effects differing from those of the diseases treated. It is also called \"allopathy\",\"western medicine\", \"orthodox medicine\", or \"cosmopolitan medicine\".\n(d) \" Alternative health care modalities \" – other forms of non-allopathic, occasionally non-indigenous or imported healing methods, though not necessarily practiced for centuries nor handed down from one generation to another. Some alternative health care modalities include reflexology, acupressure, chiropractics, nutritional therapy, and other similar methods.\n(e) \" Herbal medicines \" - finished, labelled, medicinal products that contain as active ingredient/s serial or underground part/s of plant or other materials or combination thereof, whether in the crude state or as plant preparations.\nPlant material includes juices, gums, fatty oils, essential oils, and other substances of this nature. Herbal medicines, however, may contain excipients in addition to the active ingredient(s). Medicines containing plant material(s) combined with chemically-defined active substances, including chemically-defined, isolated constituents of plants, are not considered to be herbal medicines.\n(f) \" Natural product \" - those foods that grow spontaneously in nature whether or not they are tended by man. It also refers to foods that have been prepared from grains, vegetables, fruits, nuts, meats, fish, eggs, honey, raw milk, and the like, without the use or addition of additives, preservatives, artificial colors and flavors, or manufactured chemicals of any sort after harvest or slaughter.\n(g) \" Manufacture \" - any and all operations involved in the production, including preparation, propagation, processing, formulating, filling, packing, repacking, altering, ornamenting, finishing, or otherwise changing the container, wrapper, or labelling of a consumer product in the furtherance of the distribution of the same from the original place of manufacture to the person who makes the final delivery or sale to the ultimate consumer.\n(h) \" Traditional healers \" - the relatively old, highly respected people with a profound knowledge of traditional remedies.\n(i) \" Intellectual property rights \" - is the legal basis by which the indigenous communities exercise their rights to have access to, protect, control over their cultural knowledge and product, including, but not limited to, traditional medicines, and includes the right to receive compensation for it.\nTHE PHILIPPINE INSTITUTE OF TRADITIONAL AND ALTERNATIVE HEALTH CARE"}},{"id":"PH-H6898-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Philippine Institute of Traditional and Alternative Health Care. - There is hereby established a body corporate to be known as the Philippine Institute of Traditional and Alternative Health Care, hereinafter referred to as the Institute. The Institute shall be attached to the Department of Health. Its principal flag office shall be in Metro Manila, but it may establish other branches or offices elsewhere in the Philippines as may be necessary or proper for the accomplishment of its purposes and objectives."}},{"id":"PH-H6898-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Powers and Functions. - In furtherance of its purposes and objectives, the Institute shall have the following powers and functions:\n(a) To plan and carry out research and development activities in the areas of traditional and alternative health care and its ultimate integration into the national health care delivery system;\n(b) To verify, package and transfer economically viable technologies in the field of traditional and alternative health care, giving emphasis on the social engineering aspects necessary for group endeavor;\n(c) To provide the data base or policy formulation that will stimulate and sustain production, marketing and consumption of traditional and alternative health care products;\n(d) To organize and develop continuing training programs for physicians, nurses, pharmacists, physical therapists, and other professional health workers and students, as well as scientists, research managers and extension workers in the field of traditional and alternative health care;\n(e) To formulate policies that would create public awareness through educational activities, conventions, seminars, conferences, and the like by focusing on the promotion of healthy living for preventing diseases, thereby uplifting the health care industry;\n(f) To acquire or obtain from any governmental authority whether national or local, foreign or domestic, or from any person, corporation, partnership, association or other entity, such charters, franchises, licenses, rights, privileges, assistance, financial or otherwise, and concessions as are conducive to and necessary or proper for the attainment of its purposes and objectives;\n(g) To receive and acquire from any person and/or government and private entities, whether foreign or domestic, grants, donations and contributions consisting of such properties, real or personal, including funds and valuable effects or things, as may be useful, necessary or proper to carry out its purposes and objectives and administer the same in accordance with the terms of such grants, donations and contributions, consistent with its purposes and objectives;\n(h) To serve as the coordinating center of a national network of traditional and alternative health care stations located in the different regions of the country;\n(i) To formulate a code of ethics and standards for the practice of traditional and alternative health care modalities for approval and adoption by the appropriate professional and government agencies;\n(j) To formulate standards and guidelines for the manufacture, marketing and quality control of different traditional and alternative health care materials and products for approval and adoption by the Bureau of Food and Drugs;\n(k) To coordinate with other institutions and agencies involved in the research on herbal medicines;\n(1) To adopt and use a corporate seal;\n(m) To sue and be sued in its corporate name;\n(n) To succeed by its corporate name;\n(o) To adopt its bylaws and promulgate such rules and regulations as may be necessary or proper to implement this Act, and to amend or repeal the same from time to time;\n(p) To enter into, make and execute contracts and agreements of any kind or nature;\n(q) To borrow, raise or obtain funds, or to enter into any financial or credit arrangement in order to support or carry out its research programs, finance its capital and operating expenses, subject to pertinent laws governing public debts and expenditure;\n(r) To invest in, purchase or otherwise acquire, own, hold, use, mortgage, pledge, encumber, sell, assign, convey, exchange, or otherwise deal in real and/or personal properties of whatever kind and nature, or any interest therein, including shares of stock, bonds, notes, securities and other evidences of indebtedness of natural or juridical persons, whether domestic or foreign and whether government or private;\n(s) To exercise all the powers of a corporation under the General Corporation Law, insofar as such powers are not in violation of the provisions of this Act; and\n(t) To exercise such other powers and functions, and perform other acts as may be necessary, proper or incidental to the attainment of its purposes and objectives."}},{"id":"PH-H6898-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Board of Trustees. - The corporate powers of the Institute shall be exercised, and all its business, activities and properties shall be controlled by a Board of Trustees, hereinafter referred to as the Board.\n(a) Composition. - The Board shall be composed of the following:\nSecretary of Health - ex-officio chairman Permanent representatives of the following government offices:\nDepartment of Science and Technology;\nDepartment of Environment and Natural Resources;\nDepartment of Agriculture;\nDepartment of Education, Culture and Sports; and\nCommission on Higher Education.\nRepresentatives of the following industries/sectors:\nOne (1) physician who is engaged in the practice of traditional and alternative health care;\nOne (1) member from a duly recognized academe/research institution engaged in traditional and alternative health care research;\nOne (1) traditional and alternative health care practitioner who is not a physician;\nOne (1) biomedical/allopathietwestem medical practitioner preferably from the Philippine Medical Association;\nOne (1) member from the natural food industry and/or organic food industry; and One (1) member from an environmental sector organization, The six (6) members representing the abovementioned sectors/industries shall be appointed by the President of the Philippines upon recommendation of the Secretary of Health.\nOf the appointive members, two (2) members shall have a term of three (3) years; the second two (2) members shall have a term of three (3) years; and, the third two (2) members shall each have a term of one (1) year.\nAny member appointed to a vacancy shall serve only for the unexpired term of the member whom he/she succeeded.\n(b) Meetings and quorum. - The Board shall meet regularly at least once a month or as often as the exigencies of the service demand. The presence of at least six (6) members shall constitute a quorum, and the majority vote of the members present, there being a quorum, shall be necessary for the adoption of any resolution, decision, or any other act of the Board.\n(c) Allowances and per diems. - The members of the Board shall receive a per them for every meeting actually attended subject to the pertinent budgetary laws, rules and regulations on compensation, honoraria and allowances."}},{"id":"PH-H6898-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Powers and Functions of the Board. - The Board shall exercise the following powers and functions:\n(a) To define and approve the programs, plans, policies, procedures and guidelines for the Institute in accordance with its purposes and objectives, and to control the management, operation and administration of the Institute;\n(b) To approve the Institute's organizational structure, staffing pattern, operating and capital expenditure, and financial budgets prepared in accordance with the corporate plan of the Institute;\n(c) To approve salary ranges, benefits and privileges, bonuses and other terms and conditions of service for all officers and employees of the Institute, upon recommendation of the Director General and consistent with the salary standardization and other laws;\n(d) To appoint, transfer, promote, suspend, remove or otherwise discipline any subordinate officer or employee of the Institute, upon recommendation of the Director General;\n(e) To create such committee or committees and appoint the members thereof, as may be necessary or proper for the management of the Institute or the attainment of its purposes and objectives;\n(f) To determine the research priorities of the Institute consistent with the framework of its purposes and objectives and in coordination with other government agencies; and\n(g) To exercise such other powers and functions and perform such other acts as may be necessary or proper for the attainment of the purposes and objectives of the Institute, or as may be delegated by the Secretary of Health."}},{"id":"PH-H6898-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Director General and Other Officers. - The Institute shall be headed by a Director General who shall be appointed by the President of the Philippines upon recommendation of the Secretary of Health. The Director General shall have a term of six (6) years.\nThe Director General shall be assisted by such Deputy Director General(s) and program managers/coordinators as the Board may determine to carry out the purposes and objectives of this Act."}},{"id":"PH-H6898-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Powers, Functions and Duties of the Director General. - The Director General shall have the following powers, functions and duties:\n(a) To exercise overall supervision and direction over the implementation of all research and development programs of the Institute, and to supervise and direct the management, operation and administration of the Institute;\n(b) To execute contracts, including the deeds that may incur obligations, acquire and dispose of assets and deliver documents on behalf of the Institute, within the limits of authority delegated to him by the Board;\n(c) To implement and enforce policies, decisions, orders, rules and regulations adopted by the Board;\n(d) To submit to the Board an annual report of the Institute;\n(e) To submit to the Board an annual budget and such supplemental budget as may be necessary for its consideration and approval; and\n(f) To exercise such other powers and functions and perform such other duties as may be authorized by the Board."}},{"id":"PH-H6898-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Government Agency Support and Coordination. - The Institute may, for the purpose of its research and development activities, obtain and secure the services of scholars, scientists and technical personnel of any unit of the Department of Health and other agencies of the Philippine Government. Such personnel may be paid honoraria as may be fixed and authorized by the Board following the usual government rules and regulations governing honoraria and allowances. The Institute shall also assist, cooperate and coordinate with other government agencies, such as the Bureau of Food and Drugs of the Department of Health and the Philippine Council for Health Research and Development of the Department of Science and Technology for the implementation of the purposes and objectives of this Act.\nPROMOTION OF TRADITIONAL AND ALTERNATIVE HEALTH CARE"}},{"id":"PH-H6898-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Traditional and Alternative Health Care Advocacy and Research Program. - The Institute shall promulgate a nationwide campaign to boost support for the realization of the objectives of this Act. It shall encourage the participation of non-government organizations in traditional and alternative health care and health-related projects. The Institute shall also formulate and implement a research program on the indigenous Philippine traditional health care practices performed by \"traditional healers\" using scientific research methodologies."}},{"id":"PH-H6898-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Standards for the Manufacture, Marketing and Quality Control of Traditional Medicine. - The Institute, in collaboration with the Bureau of Food and Drugs, shall formulate standards and guidelines for the manufacture, quality control and marketing of different traditional and alternative health care materials and products."}},{"id":"PH-H6898-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Incentives for the Manufacturers of Traditional and Alternative Health Care Products. - Manufacturers of traditional and alternative health care products like herbal medicinal plants shall enjoy such exemptions, deductions and other tax incentives as may be provided for under the Omnibus Investment Code, as amended."}},{"id":"PH-H6898-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Traditional and Alternative Health Care Development Fund. - To implement the provisions of this Act, there is hereby created a Traditional and Alternative Health Care Development Fund which shall be used exclusively for the programs and projects of the Institute, in the amount of Fifty million pesos (P50,000,000,00) for the first year, Seventy-five million pesos (P75,000,000.00) for the second year, and One hundred million pesos (P100,000,000.00) for the third year from the earnings of Duty Free Philippines: Provided, That not more than fifteen percent (15%) of said fund shall be used for administrative costs of the Institute.\nThereafter, such amount as may be necessary to fund the continued implementation of this Act shall be included in the annual General Appropriations Act.\nTRANSITORY PROVISIONS"}},{"id":"PH-H6898-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Appointment of Board Members. - Within thirty (30) days from the date of effectivity of this Act, the President of the Philippines shall appoint the members of the Board as well as the Director General and Deputy Director General(s)."}},{"id":"PH-H6898-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Transfer of Functions of the Traditional Medivine Unit. - Upon the establishment of the Institute, the functions, personnel and assets of the Traditional Medicine Unit and all the pharmaceutical and herbal processing plants of the Department of Health shall be transferred to the Institute without need of conveyance, transfer of assignment.\nFor the year, during which this Act was approved, the unexpended portion of the budget of the offices, agencies and units merged shall be utilized for establishing the Institute and initiating its operations, including the formulation of the rules and regulations necessary for the implementation of this Act.\nIncumbent officials and employees of the affected offices shall continue to exercise their respective functions, duties and responsibilities with the corresponding benefits and privileges. To the greatest extent possible and in accordance with existing laws, all employees of the affected offices, agencies and units shall be absorbed by the Institute.\nMISCELLANEOUS PROVISIONS"}},{"id":"PH-H6898-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Oversight Function. - The Institute shall submit to Congress an annual accomplishment report which shall include the status of its priority researches and operation. In the exercise of its oversight functions, Congress may inquire into the programs of the Institute."}},{"id":"PH-H6898-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Implementing Rules and Regulations. - Within thirty (30) days from the completion of their appointments, the Board shall convene and, in collaboration with the Department of Health - Traditional Medicine Unit, formulate the rules and regulations necessary for the implementation of this Act. Said rules and regulations shall be issued within one hundred eighty (180) days from the date of the Board's initial meeting and shall take effect upon publication in a newspaper of general circulation."}},{"id":"PH-H6898-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Repealing Clause. - All laws, decrees, executive orders, and other laws including their implementing rules and regulations inconsistent with the provisions of this Act are hereby amended, repealed or modified accordingly."}},{"id":"PH-H6898-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Separability Clause. - If any provision of this Act is declared unconstitutional or invalid, other provisions thereof which are not affected thereby shall continue in full force and effect."}},{"id":"PH-H6898-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days following its publication in the Official Gazette or in at least two (2) newspapers of general circulation."}}],"pack":"ph-p98","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Traditional and Alternative Medicine Act (TAMA) of 1997","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6899"] = {"id":"PH-H6899","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8425_1997.html","fetchedAt":"2026-10-06","articleCount":22,"structureMode":"ARTICLE","title":{"zh":"社会改革与扶贫法","en":"Social Reform and Poverty Alleviation Act","orig":"Social Reform and Poverty Alleviation Act An Act Institutionalizing the Social Reform and Poverty Alleviation Program, Creating for the Purpose the National Anti-Poverty Commission, Defining Its Powers and Functions, and for other purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8425","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-12-11","completenessNote":"全文，共 22 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8425_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6899-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. – This Act shall be known as the \"Social Reform and Poverty Alleviation Act. \""}},{"id":"PH-H6899-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of policy. – It is the policy of the State to:\n(1) Adopt an area-based, sectoral and focused intervention to poverty alleviation wherein every poor Filipino family shall be empowered to meet its minimum basic needs of health, food and nutrition, water and environmental sanitation, income security, shelter and decent housing, peace and order, education and functional literacy, participation in governance, and family care and psycho-social integrity;\n(2) Actively pursue asset reform or redistribution of productive economic resources to the basic sectors including the adoption of a system of public spending which is targeted towards the poor;\n(3) Institutionalize and enhance the Social Reform Agenda, hereinafter known as the SRA, which embodies the results of the series of consultations and summits on poverty alleviation;\n(4) Adopt and operationalize the following principles and strategies as constituting the national framework integrating various structural reforms and anti-poverty initiatives:\n(a) Social reform shall be a continuing process that addresses the basic inequities in Philippine society through a systematic package of social interventions;\n(b) The SRA shall be enhanced by government in equal partnership with the different basic sectors through appropriate and meaningful consultations and participation in governance;\n(c) Policy, programs and resource commitments from both government and the basic sectors shall be clearly defined to ensure accountability and transparency in the implementation of the Social Reform Agenda;\n(d) A policy environment conducive to sustainable social reform shall be pursued;\n(e) The SRA shall address the fight against poverty through a multi-dimensional and cross-sectoral approach which recognizes and respects the core values, cultural integrity, and spiritual diversity of target sectors and communities;\n(f) The SRA shall pursue a gender-responsive approach to fight poverty;\n(g) The SRA shall promote ecological balance in the different ecosystems, in a way that gives the basic sectors a major stake in the use, management, conservation and protection of productive resources;\n(h) The SRA shall take into account the principle and interrelationship of population and development in the planning and implementation of social reform programs thereby promoting self-help and self-reliance; and\n(i) The SRA implementation shall be focused on specific target areas and basic sectors."}},{"id":"PH-H6899-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of terms. – As used in this Act, the following terms shall mean:\n(a) \"Artisanal fisherfolk\" – Refers to municipal, small scale or subsistence fishermen who use fishing gear which do not require boats or which only require boats below three (3) tons;\n(b) \"Basic sectors\" – Refer to the disadvantaged sectors of Philippine society, namely: farmer-peasant, artisanal fisherfolk, workers in the formal sector and migrant workers, workers in the informal sector, indigenous peoples and cultural communities, women, differently-abled persons, senior citizens, victims of calamities and disasters, youth and students, children, and urban poor;\n(c) \"Cooperative\" – Refers to a duly registered association of at least fifteen (15) persons, majority of which are poor, having a common bond of interest, who voluntarily join together to achieve a lawful common social and economic end. It is organized by the members who equitably contribute the required share capital and accept a fair share of the risks and benefits of their undertaking in accordance with the universally accepted corporate principles and practices;\n(d) \"Capability building\" – Refers to the process of enhancing the viability and sustainability of microfinance institutions through activities that include training in microfinance technologies, upgrading of accounting and auditing systems, technical assistance for the installation or improvement of management information systems, monitoring of loans and other related activities. The term capability building shall in no way refer to the provision of equity investments, seed funding, partnership's seed funds, equity participation, start-up funds or any such activity that connotes the infusion of capital or funds from the government or from the people's development trust fund to microfinance institution as defined in this Act. Capability building precludes the grant of any loan or equity funds to the microfinance institution;\n(e) \"Collateral-free arrangement\" – A financial arrangement wherein a loan is contracted by the debtor without the conventional loan security of a real estate or chattel mortgage in favor of the creditor. In lieu of these conventional securities, alternative arrangements to secure the loans and ensure repayment are offered and accepted;\n(f) \"Group character loan\" – A loan contracted by a member and guaranteed by a group of persons for its repayment. The creditor can collect from any of the members of the group which guaranteed the said loan, without prejudice to the right of reimbursement of the member or members of the group who had advanced the payment in favor of the actual debtor;\n(g) \"Indigenous cultural communities/ indigenous peoples\" – As defined in Republic Act No. 8371, otherwise known as \"The Indigenous Peoples Rights Act of 1997\" ;\n(h) \"Migrant workers\" – As defined in Republic Act No. 8042, otherwise known as the \"Migrant Workers and Overseas Filipino Act of 1995\" ;\n(i) \"Micro-enterprise\" – Any economic enterprise with a capital of One hundred fifty thousand pesos (P150,000.00) and below. This amount is subject to periodic determination of the Department of Trade and Industry to reflect economic changes;\n(j) \"Microfinance\" – A credit and savings mobilization program exclusively for the poor to improve the asset base of households and expand the access to savings of the poor. It involves the use of viable alternative credit schemes and savings programs including the extension of small loans, simplified loan application procedures, group character loans, collateral-free arrangements, alternative loan repayments, minimum requirements for savings, and small denominated savers' instruments;\n(k) \"Minimum basic needs\" – Refers to the needs of a Filipino family pertaining to survival (food and nutrition; health; water and sanitation; clothing), security (shelter; peace and order; public safety; income and livelihood) and enabling (basic education and literacy; participation in community development; family and psycho-social care);\n(l) \"Human development index\" – Refers to the measure of how well a country has performed, based on social indicators of people's ability to lead a long and healthy life, to acquire knowledge and skills, and to have access to the resources needed to afford a decent standard of living. This index looks at a minimum of three outcomes of development: the state of health (measured by life expectancy at birth), the level of knowledge and skill (measured by a weighted average of adult literacy and enrollment rates), and the level of real income per capita, adjusted for poverty considerations;\n(m) \"Non-government organizations\" – Refers to duly registered non-stock, non-profit organizations focusing on the upliftment of the basic or disadvantaged sectors of society by providing advocacy, training, community organizing, research, access to resources, and other similar activities;\n(n) \"People's organization\" – Refers to a self-help group belonging to the basic sectors and/or disadvantaged groups composed of members having a common bond of interest who voluntarily join together to achieve a lawful common social or economic end;\n(o) \"Poor\" – Refers to individuals and families whose income fall below the poverty threshold as defined by the National Economic and Development Authority and/or cannot afford in a sustained manner to provide their minimum basic needs of food, health, education, housing and other essential amenities of life;\n(p) \"Poverty alleviation\" – Refers to the reduction of absolute poverty and relative poverty;\n(q) \"Absolute poverty\" – Refers to the condition of the household below the food threshold level;\n(r) \"Relative poverty\" – Refers to the gap between the rich and the poor;\n(s) \"Social reform\" – Refers to the continuing process of addressing the basic inequities in Filipino society through a systematic, unified and coordinated delivery of socioeconomic programs or packages;\n(t) \"Small Savers Instrument (SSI)\" – Refers to an evidence of indebtedness of the Government of the Republic of the Philippines which shall be in small denominations and sold at a discount from its redemption value, payable to bearer and redeemable on demand according to a schedule printed on the instrument, with a discount lower than the full stated rate if not held to maturity. The resources generated under this scheme shall be used primarily for micro-credit for the poor. SSIs are not eligible as legal reserve of banks and legal reserves prescribed of insurance companies operating in the Philippines;\n(u) \"Urban poor\" – Refers to individuals or families residing in urban centers and urbanizing areas whose income or combined household income falls below the poverty threshold as defined by the National Economic and Development Authority and/or cannot afford in a sustained manner to provide their minimum basic needs of food, health, education, housing and other essential amenities of life;\n(v) \"Workers in the formal sector\" – Refers to workers in registered business enterprises who sell their services in exchange for wages and other forms of compensation;\n(w) \"Workers in the informal sector\" – Refers to poor individuals who operate businesses that are very small in scale and are not registered with any national government agency, and to the workers in such enterprises who sell their services in exchange for subsistence level wages or other forms of compensation; and\n(x) \"Youth\" – Refers to persons fifteen (15) to thirty (30) years old."}},{"id":"PH-H6899-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Adoption and integration of Social Reform Agenda (SRA) in the National Anti-Poverty Action Agenda. – The National Anti-Poverty Action Agenda shall principally include the core principles and programs of the Social Reform Agenda (SRA). The SRA shall have a multi-dimensional approach to poverty consisting of the following reforms:\n(1) Social dimension access to quality basic services. – These are reforms which refer to equitable control and access to social services and facilities such as education, health, housing, and other basic services which enable the citizens to meet their basic human needs and to live decent lives;\n(2) Economic dimension asset reform and access to economic opportunities. – Reforms which address the existing inequities in the ownership, distribution, management and control over natural and man-made resources from which they earn a living or increase the fruits of their labor;\n(3) Ecological dimension sustainable development of productive resources. – Reforms which ensure the effective and sustainable utilization of the natural and ecological resource base, thus assuring greater social acceptability and increased participation of the basic sectors in environmental and natural resources conservation, management and development;\n(4) Governance dimension democratizing the decision-making and management processes. – Reforms which enable the basic sectors to effectively participate in decision-making and management processes that affect their rights, interests and welfare.\nThe SRA shall focus on the following sector-specific flagship programs:\n(1) For farmers and landless rural workers – agricultural development;\n(2) For the fisherfolk – fisheries and aquatic resources conservation, management and development;\n(3) For the indigenous peoples and indigenous communities – respect, protection and management of the ancestral domains;\n(4) For workers in the informal sector – workers' welfare and protection;\n(5) For the urban poor – socialized housing; and\n(6) For members of other disadvantaged groups such as the women, children, youth, persons with disabilities, the elderly, and victims of natural and man-made calamities – the Comprehensive Integrated Delivery of Social Services (CIDSS).\nAdditionally, to support the sectoral flagship programs, the following cross-sectoral flagships shall likewise be instituted:\n(1) Institution-building and effective participation in governance;\n(2) Livelihood programs;\n(3) Expansion of micro-credit/microfinance services and capability building; and\n(4) Infrastructure buildup and development.\nNATIONAL ANTI-POVERTY COMMISSION"}},{"id":"PH-H6899-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"TITLE I"},"text":{"en":"The National Anti-Poverty Commission. – To support the above-stated policy, the National Anti-Poverty Commission, hereinafter referred to as the NAPC, is hereby created under the Office of the President, which shall serve as the coordinating and advisory body for the implementation of the SRA. The Presidential Commission to Fight Poverty (PCFP), the Social Reform Council (SRC), and the Presidential Council for Countryside Development (PCCD) are hereby abolished and the NAPC shall exercise the powers and functions of these agencies. The NAPC shall be the successor-in-interest of the three (3) abolished commissions and councils.\nThe creation and operationalization of the NAPC shall be guided by the following principles:\n(1) Incorporation of the Social Reform Agenda into the formulation of development plans at the national, regional, sub-regional and local levels;\n(2) Efficiency in the implementation of the anti-poverty programs by strengthening and/or streamlining present poverty alleviation processes and mechanisms, and reducing the duplication of functions and activities among various government agencies;\n(3) Coordination and synchronization of social reform and poverty alleviation programs of national government agencies;\n(4) Exercise of policy oversight responsibilities to ensure the attainment of social reform and poverty alleviation goals;\n(5) Strengthening of local government units to more effectively operationalize the SRA in local development efforts;\n(6) Institutionalization of basic sectoral and NGO participation in effective planning, decision-making, implementation, monitoring and evaluation of the SRA at all levels;\n(7) Ensuring adequate, efficient and prompt delivery of basic services to the poor; and\n(8) Enjoining government financial institutions to open credit and savings windows for the poor, and advocating the creation of such windows for the poor among private banking institutions."}},{"id":"PH-H6899-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"TITLE I"},"text":{"en":"Composition of the NAPC. – The President of the Republic of the Philippines shall serve as Chairperson of the NAPC. The President shall appoint the Lead Convenor of the NAPC, either from the government or private sector, who shall likewise serve as the head of the National Anti-Poverty Commission Secretariat, and shall have the rank of a Cabinet Secretary. There shall be a vice-chairperson for the government sector and a vice-chairperson for the basic sectors; the former to be designated by the President, and the latter to be elected among the basic sector representatives of the NAPC as vice-chairperson for the basic sector; and the following as members:\n(1) Heads of the following government bodies:\n(a) Department of Agrarian Reform (DAR);\n(b) Department of Agriculture (DA);\n(c) Department of Labor and Employment (DOLE);\n(d) Department of Budget and Management (DBM);\n(e) Department of Social Welfare and Development (DSWD);\n(f) Department of Health (DOH);\n(g) Department of Education, Culture and Sports (DECS);\n(h) Department of the Interior and Local Government (DILG);\n(i) Department of Environment and Natural Resources (DENR);\n(j) Department of Finance (DOF);\n(k) National Economic and Development Authority (NEDA);\n(l) People's Credit and Finance Corporation (PCFC), subject to Sec. 17 of this Act; and\n(m) Presidential Commission on Urban Poor (PCUP).\n(2) Presidents of the Leagues of Local Government Units:\n(a) League of Provinces;\n(b) League of Cities;\n(c) League of Municipalities;\n(d) Liga ng mga Barangay.\n(3) Representatives from each of the following basic sectors:\n(a) Farmers and landless rural workers;\n(b) Artisanal fisherfolk;\n(c) Urban poor;\n(d) Indigenous cultural communities/indigenous peoples;\n(e) Workers in the formal sector and migrant workers;\n(f) Workers in the informal sector;\n(g) Women;\n(h) Youth and students;\n(i) Persons with disabilities;\n(j) Victims of disasters and calamities;\n(k) Senior citizens;\n(l) Nongovernment organizations (NGOs);\n(m) Children; and\n(n) Cooperatives.\nSectoral councils formed by and among the members of each sector shall respectively nominate three (3) nominees from each sector within six (6) months after the effectivity of the implementing rules and regulations of this Act, and every three (3) years thereafter and in case of vacancy. The President of the Republic of the Philippines shall, within (30) days after the submission of the list of nominees, appoint the representatives from the submitted list. Sectoral representatives shall serve for a term of three (3) years without reappointment. Appointment to any vacancy for basic sector representatives shall be only for the unexpired term of the predecessor.\nThe implementing rules and regulations (IRR) of this Act shall contain the guidelines for the formation of sectoral councils, the nomination process, recall procedures and such other mechanisms to ensure accountability of the sectoral representatives."}},{"id":"PH-H6899-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"TITLE I"},"text":{"en":"Powers and functions. – The NAPC shall exercise the following powers and functions:\n(1) Coordinate with different national and local government agencies and the private sector to assure full implementation of all social reform and poverty alleviation programs;\n(2) Coordinate with local government units in the formulation of social reform and poverty alleviation programs for their respective areas in conformity with the National Anti-Poverty Action Agenda;\n(3) Recommend policy and other measures to ensure the responsive implementation of the commitments under the SRA;\n(4) Ensure meaningful representation and active participation of the basic sectors;\n(5) Oversee, monitor and recommend measures to ensure the effective formulation, implementation and evaluation of policies, programs and resource allocation and management of social reform and poverty alleviation programs;\n(6) Advocate for the mobilization of funds by the national and local governments to finance social reform and poverty alleviation programs and capability building activities of people's organizations;\n(7) Provide financial and non-financial incentives to local government units with counterpart resources for the implementation of social reform and poverty alleviation programs; and\n(8) Submit an annual report to Congress including, but not limited to, all aspects of its operations and programs and project implementation, financial status and other relevant data as reflected by the basic reform indicator."}},{"id":"PH-H6899-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"TITLE I"},"text":{"en":"Principal office. – The NAPC shall establish its principal office in Metro Manila and may establish such branches within the Philippines as may be deemed necessary by the President of the Philippines to carry out the powers and functions of the NAPC."}},{"id":"PH-H6899-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"TITLE I"},"text":{"en":"The NAPC secretariat. – The NAPC shall be supported by a Secretariat, which shall be headed by the Lead Convenor referred to under Sec. 6 hereof. The Secretariat shall provide technical and administrative support to the NAPC. It shall be formed from the unification of the secretariats of the following bodies:\n(1) Presidential Commission to Fight Poverty (PCFP);\n(2) Social Reform Council (SRC); and\n(3) Presidential Council for Countryside Development (PCCD).\nWithin three (3) months from the effectivity of this Act, the Office of the President shall finalize the organizational plan for the NAPC.\nTo provide the continuity of existing social reform and poverty alleviation related programs, all accredited organizations under the three (3) unified councils and commissions shall be automatically accredited under the NAPC until such time that additional accreditation requirements may be provided by the NAPC."}},{"id":"PH-H6899-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"TITLE I"},"text":{"en":"The People's Development Trust Fund. – The People's Development Trust Fund (PDTF) is hereby established, which shall be monitored by the NAPC.\nThe Trust Fund in the amount of Four billion and five hundred million pesos (P4,500,000,000.00) shall be funded from the earnings of the PAGCOR in addition to appropriations by Congress, voluntary contributions, grants, gifts from both local and foreign sources as may be accepted or decided on by the NAPC. Any additional amount to the Trust Fund shall form part of the corpus of the Trust Fund, unless the donor, contributor or grantor expressly provides as a condition that the amount be included in the disbursible portion of the Trust Fund.\nThe President of the Philippines shall assign to any existing government department or agency the administration of the Trust Fund, based on the expertise, organizational capability, and orientation or focus of the department or agency. The NAPC shall be limited to the function of monitoring the utilization of the PDTF, while the government departments or agencies designated by the President shall directly administer the utilization of the earnings of the PDTF.\nOnly the fruits of the PDTF shall be used for the purposes provided in this Act. Any undisbursed fruits for the preceding year shall form part of the disbursible portion of the PDTF in the following year.\nFor the purpose of monitoring the earnings of the PDTF, the NAPC shall:\n(1) Source funds for the establishment of and augmentation to the Trust Fund;\n(2) Recommend to the appropriate government department or agency the accreditation of organizations and institutions that shall act as resource partners in conducting institutional development and capability building activities for accredited organizations and beneficiaries of microfinance and micro-enterprise programs;\n(3) Ensure that validation and monitoring activities are conducted for funded institutional development and capability building projects/programs/beneficiaries; and\n(4) Promote research and development work on livelihood and microfinance technology and publications/communications programs that assist the poor beneficiaries."}},{"id":"PH-H6899-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"TITLE I"},"text":{"en":"Purposes of the People's Development Trust Fund (PDTF). – The earnings of the PDTF shall be utilized for the following purposes:\n(1) Consultancy and training services for microfinance institutions and their beneficiaries on the establishment of the necessary support services, social and financial preparation of beneficiaries, preparation of plans and programs including fund sourcing and assistance, establishment of credit and savings monitoring and evaluation mechanisms;\n(2) Scholarships or training grants for microfinance staff and officers, and selected beneficiaries;\n(3) Community organizing for microfinance, livelihood and micro-enterprises training services;\n(4) Livelihood/micro-enterprise project/program feasibility studies and researches;\n(5) Savings mobilization and incentive programs, and other similar facilities;\n(6) Information and communication systems such as baseline surveys, development monitoring systems, socioeconomic mapping surveys, organizational assessments, and other similar activities;\n(7) Legal and other management support services such as registration, documentation, contract review and enforcement, financial audit and operational assessment;\n(8) Information dissemination of microfinance technology; and\n(9) Other activities to support microfinance as approved by the designated agency administering the PDTF.\nThe PDTF may be accessed by the following:\n(a) Registered microfinance organizations engaged in providing micro-enterprise services for the poor to enable them to become viable and sustainable;\n(b) Local government units providing microfinance and micro-enterprise programs to their constituents: Provided , That the PDTF shall not be used by the LGUs for personal services and maintenance and other operating expenses; and\n(c) Local government units undertaking self-help projects where at least twenty-five percent (25%) of the total earnings of the PDTF shall be used exclusively for the provision of materials and technical services."}},{"id":"PH-H6899-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"TITLE I"},"text":{"en":"The role of Local Government Units (LGUs). – The local government units, through the local development councils of the province, city, municipality, or barangay shall be responsible for the formulation, implementation, monitoring and evaluation of the National Anti-Poverty Action Agenda in their respective jurisdictions. The LGUs shall:\n(a) Identify the poor in their respective areas based on indicators such as the minimum basic needs approach and the human development index, their location, occupation, nature of employment, and their primary resource base and formulate a provincial/city/municipality anti-poverty action agenda;\n(b) Identify and source funding for specific social reform and poverty alleviation projects;\n(c) Coordinate, monitor and evaluate the efforts of local government units with the private sector on planning and implementation of the local action program for social reform and poverty alleviation; and\n(d) Coordinate and submit progress reports to the National Anti-Poverty Commission regarding their local action programs.\nNothing in this Act shall be construed as diminishing the powers granted to the local government units under the Local Government Code.\nMICROFINANCE SERVICES FOR THE POOR"}},{"id":"PH-H6899-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"TITLE II"},"text":{"en":"Microfinance program. – The programs and implementing mechanisms of the Social Reform Agenda's Flagship Program on Credit shall be integrated, adopted and further enhanced to effectively support the objectives of this Act along the following thrusts:\n(1) Development of a policy environment, especially in the area of savings generation, supportive of basic sector initiatives dedicated to serving the needs of the poor in terms of microfinance services;\n(2) Rationalization of existing government programs for credit and guarantee;\n(3) Utilization of existing government financial entities for the provision of microfinance products and services for the poor; and\n(4) Promotion of mechanisms necessary for the implementation of microfinance services, including indigenous microfinance practices."}},{"id":"PH-H6899-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"TITLE II"},"text":{"en":"People's Credit and Finance Corporation (PCFC). – The People's Credit and Finance Corporation (PCFC), a government- controlled corporation registered with the Securities and Exchange Commission and created in accordance with Administrative Order No. 148 and Memorandum Order No. 261, shall be the vehicle for the delivery of microfinance services for the exclusive use of the poor. As a government-owned and -controlled corporation, it shall be the lead government entity specifically tasked to mobilize financial resources from both local and international funding sources for microfinance services for the exclusive use of the poor."}},{"id":"PH-H6899-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"TITLE II"},"text":{"en":"Increase in the Capitalization of PCFC. – To facilitate the increase in the capitalization of the PCFC, the President of the Republic of the Philippines shall take measures to enable the amendment of the Articles of Incorporation of the PCFC such that:\n(a) The authorized capital stock of the PCFC may be increased from One hundred million pesos (P100,000,000.00) to Two billion pesos (P2,000,000,000.00) divided into twenty million common shares with a par value of One hundred pesos (P100.00) per share;\n(b) The subscribed capital stock may be increased from One hundred million pesos (P100,000,000.00) to Six hundred million pesos (P600,000,000.00) and the national government may subscribe the difference of Five hundred million pesos (P500,000,000.00);\n(c) The initial paid-up capital may be increased from One hundred million pesos (P100,000,000.00) to Two hundred fifty million pesos (P250,000,000.00), to be increased subsequently to a total of Six hundred million pesos (P600,000,000.00), such that at the end of a period of four (4) years the subscribed capital shall be fully paid-up, in the following manner:\nFor the initial increase in paid-up capital during the first year, the difference of One hundred fifty million pesos (P150,000,000.00) shall be paid and appropriated for by government; for the second year, One hundred fifty million pesos (P150,000,000.00); for the third year, One hundred million pesos (P100,000,000.00); and for the fourth year, One hundred million pesos (P100,000,000.00).\nThe appropriations for the additional paid-up capital shall be sourced from the share of the national government in the earnings of the PAGCOR, in the manner provided for under Sec. 18, which provides for the appropriations under this Act."}},{"id":"PH-H6899-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"TITLE II"},"text":{"en":"Special credit windows in existing Government Financing Institutions (GFIs). – The existing government financial institutions shall provide for the savings and credit needs of the poor. The GFIs such as the Land Bank of the Philippines, Philippine Postal Bank, Al Amanah Bank, and the Development Bank of the Philippines are hereby mandated to coordinate with NAPC and PCFC in setting up special credit windows and other arrangements, such as the servicing of Small Savers Instruments (SSIs), that will promote the microfinance program of this Act.\nThe private financing institutions may also provide the savings and credit requirements of the poor by setting up similar credit windows and other arrangements to promote the savings component of the microfinance program of this Act.\nSpecial credit windows for the poor shall, as far as practicable, include an allocation for the basic sectors, as defined in this Act, particularly those living in the rural areas, agrarian reform communities, and women in the countryside."}},{"id":"PH-H6899-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"TITLE II"},"text":{"en":"PCFC privatization. – In the event that the ownership of the majority of the issued voting stocks of PCFC shall have passed to private investors (exclusively qualified nongovernment organizations, people's organizations and cooperatives), the stockholders shall cause the registration with the Securities and Exchange Commission (SEC) of the revised Articles of Incorporation and By-laws. The PCFC shall thereafter be considered as a privately organized entity subject to the laws and regulations generally applied to private corporations.\nThe chairman of the PCFC may still be a member of the National Anti-Poverty Commission (NAPC) upon the privatization of the PCFC: Provided, That the PCFC will continue its main purpose of providing for the savings and credit needs of the poor.\nAPPROPRIATIONS FOR THE NATIONAL ANTI-POVERTY COMMISSION (NAPC) AND THE PEOPLE'S DEVELOPMENT TRUST FUND (PDTF)"}},{"id":"PH-H6899-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"TITLE III"},"text":{"en":"Appropriations. – To carry out the provisions of this Act, the following amounts are appropriated as follows:\n(1) The sum of One hundred million pesos (P100,000,000.00) is hereby appropriated as the initial operating fund in addition to the unutilized funds of the rationalized commission and councils. The sum shall be sourced from the President's Contingent Fund. In subsequent years, the amount necessary to implement this Act shall be included in the annual appropriations. The said amounts shall be under the management of the NAPC.\n(2) The aggregate sum of Four billion and five hundred million pesos (P4,500,000,000.00) for ten (10) years is hereby appropriated for the establishment of the People's Development Trust Fund (PDTF) from the share of the national government in the earnings of the Philippine Amusement and Gaming Corporation (PAGCOR), in the following manner: on the first year, Three hundred fifty million pesos (P350,000,000.00); on the second year, Three hundred fifty million pesos (P350,000,000.00); on the third year, Four hundred million pesos (P400,000,000.00); on the fourth year, Four hundred million pesos (P400,000,000.00); on the fifth year and every year thereafter until the tenth year, Five hundred million pesos (P500,000,000.00) annually.\n(3) The aggregate sum of Five hundred million pesos (P500,000,000) for four years shall be appropriated for the increase in the capitalization of the PCFC, from the share of the national government in the earnings of the PAGCOR, at such time that the increase in the capitalization of the PCFC, in the manner provided for under Sec. 15 of this Act, shall have been effected. The appropriation shall be made in the following manner: on the first year, One hundred fifty million pesos (P150,000,000.00); on the second year, One hundred fifty million pesos (P150,000,000.00); on the third year, One hundred million pesos (P100,000,000.00); and on the fourth year, One hundred million pesos (P100,000,000.00)."}},{"id":"PH-H6899-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"TITLE III"},"text":{"en":"Transitory provision. – The Social Reform Council (SRC) and the representatives therein shall, in temporary capacity, exercise the powers and assume the duties of the NAPC until such time that the members of NAPC shall have been duly appointed or designated.\nThe Office of the President shall formulate the implementing rules and regulations (IRR) of this Act within six (6) months after its effectivity.\nThe assets, liabilities and personnel of PCFP, SRC and PCCD are hereby transferred to the NAPC. Personnel who cannot be absorbed by NAPC shall be entitled to a separation pay of one-and-a-half (1 1/2) months for every year of service and other benefits under existing retirement laws, at the option of the personnel concerned."}},{"id":"PH-H6899-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"TITLE III"},"text":{"en":"Repealing clause. – All laws, executive orders, rules and regulations, or parts thereof, inconsistent with this Act are hereby repealed, amended or modified accordingly. The provisions of this Act shall not be repealed, amended or modified unless expressly provided in subsequent general or special laws."}},{"id":"PH-H6899-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"TITLE III"},"text":{"en":"Separability clause. – If any provision of this Act shall be held invalid or unconstitutional, the remaining provisions thereof not affected thereby shall remain in full force and effect."}},{"id":"PH-H6899-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"TITLE III"},"text":{"en":"Effectivity clause. – This Act shall be effective on June 30, 1998."}}],"pack":"ph-p98","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Social Reform and Poverty Alleviation Act","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6900"] = {"id":"PH-H6900","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8426_1997.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立San Fernando市","en":"An Act Converting the La Union National High School - Mameltac Extension in the Municipality of San Fernando, Province of La Union, Into An Independent National High School, to Be Known as the Dr. Quintin Balcita, Sr. National High School, and Appropriating Funds Therefor","orig":"An Act Converting the La Union National High School - Mameltac Extension in the Municipality of San Fernando, Province of La Union, Into An Independent National High School, to Be Known as the Dr. Quintin Balcita, Sr. National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["labor","education"],"docNumber":"Republic Act No. 8426","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-12-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8426_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6900-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The La Union National High School – Mameltac Extension in the Municipality of San Fernando, Province of La Union, shall be converted into an independent national high school to be known as the Dr. Quintin Balcita, Sr. National High School.\nThe Dr. Quintin Balcita, Sr. National High School shall remain under the supervision of the Department of Education, Culture and Sports."}},{"id":"PH-H6900-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the La Union National High School - Mameltac Extension. Thereafter, such sums as may be necessary for the operation and maintenance of the Dr. Quintin Balcita, Sr. National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H6900-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p98"};
  FT["PH-H6901"] = {"id":"PH-H6901","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8427_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Kitcharao市","en":"An Act Establishing a National High School in Barangay Poblacion, Municipality of Kitcharao, Province of Agusan Del Norte, to Be Known as Kitcharao National High School, and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Poblacion, Municipality of Kitcharao, Province of Agusan Del Norte, to Be Known as Kitcharao National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8427","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-12-15","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8427_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6901-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"A national high school is hereby established in Barangay Poblacion, Municipality of Kitcharao, Province of Agusan del Norte, to be known as the Kitcharao National High School."}},{"id":"PH-H6901-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports (DECS) shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H6901-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6901-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p98"};
  FT["PH-H6902"] = {"id":"PH-H6902","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8428_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Palapag市","en":"An Act Establishing a National High School in Barangay Capacujan, Municipality of Palapag, Second District of Northern Samar, to Be Known as the Capacujan National High School, and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Capacujan, Municipality of Palapag, Second District of Northern Samar, to Be Known as the Capacujan National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8428","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-12-15","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8428_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6902-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Education, Culture and Sports, a national high school in Barangay Capacujan, Municipality of Palapag, Second District of Northern Samar, to be known as the Capacujan National High School."}},{"id":"PH-H6902-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall implement this Act so as to make the school in operation during the first school term after the effectivity of this Act."}},{"id":"PH-H6902-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6902-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p98"};
  FT["PH-H6903"] = {"id":"PH-H6903","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8429_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Loay市","en":"An Act Establishing the Sagnap National High School in Barangay Sagnap in the Municipality of Loay, Province of Bohol, and Appropriating Funds Therefor","orig":"An Act Establishing the Sagnap National High School in Barangay Sagnap in the Municipality of Loay, Province of Bohol, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8429","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-12-15","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8429_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6903-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a national high school in Barangay Sagnap in the Municipality of Loay, Province of Bohol, to be known as the Sagnap National High School."}},{"id":"PH-H6903-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary for the implementation of this Act."}},{"id":"PH-H6903-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6903-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p98"};
  FT["PH-H6904"] = {"id":"PH-H6904","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8430_1997.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Munai市","en":"An Act Establishing a Municipal High School in the Municipality of Munai, Province of Lanao Del Norte, to Be Known as the Munai National High School, and Appropriating Funds Therefor","orig":"An Act Establishing a Municipal High School in the Municipality of Munai, Province of Lanao Del Norte, to Be Known as the Munai National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8430","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-12-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8430_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6904-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Department of Education, Culture and Sports, a municipal high school in the Municipality of Munai, Province of Lanao del Norte, to be known as the Munai National High School."}},{"id":"PH-H6904-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6904-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p98"};
