  FT["PH-H6937"] = {"id":"PH-H6937","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1998/ra_8463_1998.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Gingoog市","en":"An Act Establishing a National High School in Barangay San Luis in the City of Gingoog, to Be Known as the San Luis National High School, and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay San Luis in the City of Gingoog, to Be Known as the San Luis National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8463","issuingBody":"Congress of the Philippines","promulgatedDate":"1998-01-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1998/ra_8463_1998.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6937-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a high school in Barangay San Luis, City of Gingoog, Province of Misamis Oriental, to be known as the San Luis National High School."}},{"id":"PH-H6937-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H6937-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6937-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p98"};
  FT["PH-H6938"] = {"id":"PH-H6938","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1998/ra_8464_1998.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在新怡诗夏省Gapan市镇Kapalangan设立中学，名称为Kapalangan国立中学，并为此拨款的法案","en":"An Act Establishing a High School in Kapalangan, Gapan, Nueva Ecija, to Be Known as the Kapalangan National High School, and Appropriating Funds Therefor","orig":"An Act Establishing a High School in Kapalangan, Gapan, Nueva Ecija, to Be Known as the Kapalangan National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8464","issuingBody":"Congress of the Philippines","promulgatedDate":"1998-01-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1998/ra_8464_1998.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6938-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Department of Education, Culture and Sports (DECS), a high school in Barangay Kapalangan, Gapan, Nueva Ecija, to be known as the Kapalangan National High School."}},{"id":"PH-H6938-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H6938-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the annual General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6938-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect immediately upon its approval."}}],"pack":"ph-p98","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing a High School in Kapalangan, Gapan, Nueva Ecija, to Be Known as the Kapalangan National High School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
